attempts.query:
PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT (COUNT(DISTINCT ?pub) AS ?n) WHERE {
  ?id a afiliaciones:Identification ;
      afiliaciones:identifies <https://ror.org/03cqe8w59> ;
      afiliaciones:ofMention ?m .
  ?m afiliaciones:inPublication ?pub .
}

PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT DISTINCT ?org WHERE {
  ?pub a afiliaciones:Publication ;
       afiliaciones:doi "10.1001/jamaneurol.2025.0023" .
  ?m afiliaciones:inPublication ?pub .
  ?id a afiliaciones:Identification ;
      afiliaciones:ofMention ?m ;
      afiliaciones:identifies ?org .
}

PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT (COUNT(DISTINCT ?org) AS ?n) WHERE {
  ?id a afiliaciones:Identification ;
      afiliaciones:ofMention ?m ;
      afiliaciones:identifies ?org .
  ?m a afiliaciones:AffiliationMention ;
     afiliaciones:inPublication ?p .
  ?p a afiliaciones:Publication .
}

PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT DISTINCT ?doi WHERE {
  ?id a afiliaciones:Identification ;
      afiliaciones:identifies <https://ror.org/0081fs513> ;
      afiliaciones:ofMention ?m .
  ?m afiliaciones:inPublication ?p .
  ?p afiliaciones:doi ?doi .
}
ORDER BY ?doi

PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT (COUNT(DISTINCT ?m) AS ?n) WHERE {
  ?m a afiliaciones:AffiliationMention ;
     afiliaciones:affiliationText ?t .
  FILTER(CONTAINS(LCASE(STR(?t)), "argentin"))
  FILTER NOT EXISTS {
    ?i a afiliaciones:Identification ;
       afiliaciones:ofMention ?m ;
       afiliaciones:identifies ?o .
  }
}
